};
// La I y la D se recalculan cada 5 ms o más; en vueltas más cortas solo cambia la P.
const unsigned long PID_MUESTRA_US = 5000UL;
inline float pid_limitar(float valor, float limite) {
    return valor > limite ? limite : valor < -limite ? -limite : valor;
}
inline void pid_reiniciar(RbPid& pid) {
    pid.integral = 0;
    pid.anterior = 0;
    pid.error = 0;
    pid.p = 0;
    pid.i = 0;
    pid.d = 0;
    pid.salida = 0;
    pid.iniciado = false;
}
static RbPid pid_estado[{PIDS_TOTAL}];
inline RbPid& pid_control(int n, const char* bloque) {
    static RbPid vacio;
    int total = int(sizeof(pid_estado) / sizeof(pid_estado[0]));
    if (n < 1 || n > total || !pid_estado[n - 1].configurado) {
        rb_fail(bloque, "Configura el PID al iniciar");
        return vacio;
    }
    return pid_estado[n - 1];
}
// filas: Kp, Ki, Kd y límite de cada PID, uno tras otro.
inline void pid_configurar(int inicio, const float* filas, int cantidad, const char* bloque) {
    for (int n = 0; n < cantidad; n++) {
        const float* fila = filas + 4 * n;
        if (!(fila[3] > 0)) {
            rb_fail(bloque, "El límite del PID debe ser mayor que 0");
            return;
        }
        RbPid& pid = pid_estado[inicio + n];
        pid.kp = fila[0];
        pid.ki = fila[1];
        pid.kd = fila[2];
        pid.limite = fila[3];
        pid.configurado = true;
        pid_reiniciar(pid);
    }
}
inline void pid_actualizar(int n, float error, const char* bloque) {
    RbPid& pid = pid_control(n, bloque);
    error = rb_finite(error, bloque);
    if (rb_failed) return;
    unsigned long ahora = micros();
    pid.error = error;
    pid.p = pid.kp * error;
    if (!pid.iniciado) {
        // Primera vuelta: todavía no hay tiempo ni error anterior, así que D = 0.
        pid.iniciado = true;
        pid.ultimo = ahora;
        pid.anterior = error;
        pid.d = 0;
    } else {
        unsigned long pasado = ahora - pid.ultimo;
        if (pasado >= PID_MUESTRA_US) {
            float dt = pasado / 1000000.0f;
            if (pid.ki != 0) {
                // Anti-windup: la I sola nunca supera el límite.
                float tope = pid.limite / fabs(pid.ki);
                pid.integral = pid_limitar(pid.integral + error * dt, tope);
            }
            pid.d = pid.kd * (error - pid.anterior) / dt;
            pid.anterior = error;
            pid.ultimo = ahora;
        }
    }
    pid.i = pid.ki * pid.integral;
    pid.salida = pid_limitar(pid.p + pid.i + pid.d, pid.limite);
}
inline void pid_cambiar(int n, float kp, float ki, float kd, const char* bloque) {
    RbPid& pid = pid_control(n, bloque);
    kp = rb_finite(kp, bloque);
    ki = rb_finite(ki, bloque);
    kd = rb_finite(kd, bloque);
    if (rb_failed) return;
    pid.kp = kp;
    pid.ki = ki;
    pid.kd = kd;
}
inline float pid_parte(int n, const String& parte, const char* bloque) {
    RbPid& pid = pid_control(n, bloque);
    if (parte == "p") return pid.p;
    if (parte == "i") return pid.i;
    if (parte == "d") return pid.d;
    return pid.error;
}
